package vn.crossdock;
import org.springframework.stereotype.Service;import org.apache.pdfbox.pdmodel.*;import org.apache.pdfbox.pdmodel.font.PDType0Font;import org.apache.pdfbox.pdmodel.common.PDRectangle;
import java.io.*;import java.util.*;import static vn.crossdock.Db.*;
@Service public class PdfService {
 final Db db;public PdfService(Db d){db=d;}
 public byte[] trip(long id)throws IOException {var t=db.get("chuyen_xuat",id);require(Set.of("SHIPPED","DONE").contains(s(t,"status")),"Chỉ in phiếu sau khi xuất kho thực tế");var vehicle=db.get("xe",n(t,"vehicle_id"));var user=db.get("nguoi_dung",n(t,"dispatched_by"));List<String> lines=new ArrayList<>();lines.add("PHIẾU XUẤT KHO VÀ BÀN GIAO VẬN CHUYỂN");lines.add("Kho xuất: Bình Dương • "+s(t,"code"));lines.add("Ngày giờ xuất: "+t.get("dispatched_at"));lines.add("Nhân viên lập phiếu: "+s(user,"name"));lines.add("Xe: "+s(vehicle,"code")+" • Biển số: "+s(vehicle,"plate"));lines.add("Tài xế: "+s(t,"driver")+" • Miền: "+s(t,"region"));double total=d(db.one("select coalesce(sum(b.gross_kg),0) kg from phan_bo_thung a join thung_hang b on b.id=a.box_id join diem_giao_chuyen s on s.id=a.stop_id where s.trip_id=? and a.status<>'CANCELLED'",id),"kg");lines.add("Tổng trọng lượng cả bì: "+total+" kg");
 for(var stop:db.rows("select s.*, c.code customer_code,c.name customer_name from diem_giao_chuyen s join dia_diem_giao l on l.id=s.location_id join khach_hang c on c.id=l.customer_id where s.trip_id=? and exists(select 1 from phan_bo_thung a where a.stop_id=s.id and a.status<>'CANCELLED') order by s.sequence_no",id)){lines.add("");lines.add("ĐIỂM GIAO "+stop.get("sequence_no"));lines.add("Khách hàng: "+s(stop,"customer_name")+" • Mã: "+s(stop,"customer_code"));lines.add("Địa chỉ: "+s(stop,"address_snapshot"));for(var b:db.rows("select b.*,p.code sku,p.name part_name from phan_bo_thung a join thung_hang b on b.id=a.box_id join linh_kien p on p.id=b.part_id where a.stop_id=? and a.status<>'CANCELLED' order by b.id",n(stop,"id"))){lines.add(s(b,"code")+" | "+s(b,"sku")+" - "+s(b,"part_name"));lines.add("Số lượng: "+b.get("quantity")+" • Trọng lượng cả bì: "+b.get("gross_kg")+" kg");}lines.add("Người giao: ______________  Người nhận: ______________");}return write(lines);}
 byte[] write(List<String> lines)throws IOException {try(var doc=new PDDocument();var out=new ByteArrayOutputStream();var stream=getClass().getResourceAsStream("/fonts/DejaVuSans.ttf")){var font=PDType0Font.load(doc,stream);PDPageContentStream cs=null;float y=0;try{for(String raw:lines){String clean=raw.replaceAll("[\\r\\n\\t]"," ");List<String> wraps=new ArrayList<>();String line="";for(String word:clean.split(" ")){if((line+word).length()>83){wraps.add(line);line="";}line+=word+" ";}wraps.add(line);for(String l:wraps){if(cs==null||y<55){if(cs!=null)cs.close();var page=new PDPage(PDRectangle.A4);doc.addPage(page);cs=new PDPageContentStream(doc,page);y=790;}cs.beginText();cs.setFont(font,10);cs.newLineAtOffset(42,y);cs.showText(l);cs.endText();y-=18;}}}finally{if(cs!=null)cs.close();}doc.save(out);return out.toByteArray();}}
}
